package com.restaurantmanagement.config; import com.restaurantmanagement.entity.*; import com.restaurantmanagement.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder; @Configuration public class DemoDataConfig { @Bean CommandLineRunner demo(RestaurantRepository restaurants,UserRepository users,PasswordEncoder encoder){return x->{if(restaurants.count()==0){var r=new Restaurant();r.name="Saffron Table";r.email="hello@saffron.local";r.phone="+1 555 0100";r.city="Austin";r.cuisineType="Indian";restaurants.save(r);}if(users.count()==0){var u=new AppUser();u.email="admin@omni.local";u.passwordHash=encoder.encode("ChangeMe123!");u.role="SUPER_ADMIN";users.save(u);}};} }
